window.COURSE_DATA = {"sesiones": [{"n": 1, "kicker": "Sesión 1 · 3 horas · bloques S1.1 a S1.7", "titulo": "Abuso sexual infantil: trauma, poder, desarrollo y contexto", "subtitulo": "Contenido sensible. Sin detalles gráficos. Casos ficticios. Material educativo: no sustituye evaluación clínica, protocolo ni supervisión.", "pausa": "Pausa de 10 minutos entre S1.3 y S1.4. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "Tres horas para mirar el abuso sexual infantil desde la clínica, el desarrollo y el contexto. El objetivo no es diagnosticar ni investigar. Es entender lo que una niña o un niño puede estar viviendo y responder de una forma que no le haga más daño.", "items": [{"h": "Poder y silenciamiento", "t": "Cómo la diferencia de edad, la autoridad y la dependencia hacen posible el abuso y dificultan que la persona lo cuente."}, {"h": "Desarrollo y variabilidad", "t": "Por qué las manifestaciones cambian con la edad, y por qué ninguna señal aislada confirma ni descarta un abuso."}, {"h": "Trauma en contexto", "t": "Qué distinguimos entre evento, experiencia, respuesta y diagnóstico, y cuándo el concepto de trauma complejo sirve."}, {"h": "Abordaje sensible", "t": "Cómo acompañar sin revictimizar, y en qué se diferencia la atención clínica de una investigación."}]}, {"bloque": "S1.1", "tipo": "texto", "titulo": "Un marco que no culpabiliza: tres principios para toda la sesión", "items": [{"h": "La responsabilidad siempre es de quien agrede", "t": "Ningún niño o adolescente es responsable de lo que le hacen. Tampoco lo es de su silencio, de sus reacciones posteriores ni de no haberse alejado. Esta idea guía todo lo que sigue en la sesión."}, {"h": "El bienestar y la seguridad son la referencia", "t": "Tomamos como punto de partida el bienestar, la seguridad y la autonomía progresiva de la niña o niño. No podemos asumir que su entorno familiar es seguro, aunque sea el suyo y aunque sea donde vive."}, {"h": "Los ejemplos son narrados y no describen escenas", "t": "Los casos son ficticios, mínimos y sin detalles gráficos. Lo que importa es la lectura clínica: qué pasa, qué necesita la persona, qué protege y qué conviene evitar."}], "destacado": "Aquí no buscamos culpables ni confirmamos hechos. Buscamos entender y proteger."}, {"bloque": "S1.2", "tipo": "flujo", "titulo": "Evento, experiencia, respuesta y diagnóstico no son lo mismo", "items": [{"h": "Evento", "t": "Es lo que sucedió en el mundo. Muchas veces no sabemos con precisión qué pasó, cuándo ni cuántas veces, y no es nuestra tarea reconstruirlo."}, {"h": "Experiencia subjetiva", "t": "Es lo que la niña o el niño vive: lo que siente, lo que entiende y lo que teme. Dos personas pueden atravesar el mismo evento y vivirlo de formas muy distintas."}, {"h": "Respuestas posteriores", "t": "Aparecen en la conducta, el ánimo, el sueño, la escuela o el cuerpo. Pueden ser adaptativas, pueden persistir y pueden cambiar con el tiempo."}, {"h": "Diagnóstico", "t": "Es una conclusión que solo se alcanza con criterios específicos y evaluación clínica. Nunca se deduce de un evento ni de una conducta aislada."}], "destacado": "Confundir estos niveles lleva a diagnosticar sin evaluación, o a dudar de un relato solo porque no encaja en una categoría."}, {"bloque": "S1.2", "tipo": "texto", "titulo": "Trauma complejo: un término descriptivo que se usa con precisión", "items": [{"h": "Qué describe", "t": "El término describe una historia de exposición repetida o prolongada a experiencias traumáticas, sobre todo interpersonales y de las que es difícil escapar. En la infancia, esto suele ocurrir dentro de vínculos de cuidado, que son justo los que deberían proteger."}, {"h": "Qué no es", "t": "No es sinónimo de TEPT ni una etiqueta informal para una persona. La CIE-11 incluye un diagnóstico de TEPT complejo con criterios propios, mientras que el DSM-5 no lo incluye. Por eso no debe usarse como atajo para nombrar un caso."}, {"h": "Por qué importa", "t": "Orienta una evaluación más amplia que el síntoma aislado: la historia, la seguridad actual y la forma en que la experiencia afecta la regulación emocional, la imagen de sí mismo y las relaciones."}], "destacado": "Un marco sirve para preguntar mejor. Un diagnóstico exige criterios y evaluación."}, {"bloque": "S1.2", "tipo": "texto", "titulo": "La edad y la dependencia cambian la forma de leer una experiencia", "items": [{"h": "Lo que la niña puede decir", "t": "Un niño pequeño puede no tener palabras para lo que vive. Un adolescente puede tenerlas y aun así evitar usarlas. La falta de relato no equivale a ausencia de experiencia."}, {"h": "La dependencia limita las opciones", "t": "En la infancia, el vínculo con los adultos determina la seguridad. Cuanto más dependiente es el niño de quien le hace daño, menos opciones tiene para alejarse o pedir ayuda."}, {"h": "El contexto modifica el riesgo", "t": "Las condiciones de vida, la escuela, la comunidad y la red de apoyo cambian tanto el riesgo como la recuperación. Leer una experiencia sin ese contexto lleva a conclusiones incompletas."}], "destacado": "La pregunta clínica no es qué le pasó exactamente, sino qué necesita hoy y qué la protege."}, {"bloque": "S1.3", "tipo": "texto", "titulo": "Poder: la asimetría que hace posible el abuso y el silencio", "items": [{"h": "Diferencia de edad, autoridad y posición", "t": "Quien agrede suele tener más edad, más poder social o una posición de cuidado o confianza. Esa diferencia hace que el niño no pueda negarse ni decidir como lo haría un adulto en igualdad de condiciones."}, {"h": "La confianza como puerta de entrada", "t": "Muchas situaciones empiezan con afecto, regalos, juegos o atención especial. La confianza sirve primero para acercarse y después para sostener el secreto."}, {"h": "La dependencia afectiva", "t": "El niño puede querer a quien le hace daño, depender de esa persona para cuidados básicos o sentir lealtad. Nada de eso es consentimiento: es una relación desigual que se vuelve difícil de romper."}], "destacado": "Que el niño no se haya ido ni lo haya contado no significa que no haya habido abuso, ni que lo haya querido."}, {"bloque": "S1.3", "tipo": "tarjetas", "titulo": "Coerción, manipulación y secreto: cómo se sostiene el silencio", "intro": "Estos mecanismos rara vez aparecen solos. Suelen combinarse, y cada uno refuerza al otro. Lo que se busca es que la niña o el niño sienta que contar tendrá un costo mayor que callar.", "items": [{"h": "Amenazas", "t": "Pueden dirigirse al niño, a su familia o a una mascota. Pueden ser explícitas o insinuadas, y el niño suele tomarlas muy en serio porque conoce bien a quien las hace."}, {"h": "Manipulación y culpa", "t": "Se le hace sentir responsable, cómplice o culpable. También se le convence de que nadie le creería, o de que contar arruinaría a alguien que quiere."}, {"h": "Secreto", "t": "Se presenta como algo especial, como una forma de proteger a alguien o como un juego entre dos. Con el tiempo, el secreto se convierte en una carga que el niño no sabe cómo soltar."}, {"h": "Premios y castigos", "t": "Regalos, privilegios o castigos vinculan el silencio con la seguridad o con las pérdidas. Así se refuerza la dependencia y se vuelve más difícil hablar."}]}, {"bloque": "S1.3", "tipo": "texto", "titulo": "El silencio se explica por el entorno, no solo por el niño", "items": [{"h": "Factores familiares", "t": "Conflictos graves, ausencia de adultos protectores, normalización de la violencia o miedo a romper la unidad familiar pueden volver muy difícil hablar. A veces el adulto que debería proteger es quien tiene más poder en casa."}, {"h": "Factores sociales", "t": "El estigma, la vergüenza, los rumores y frases como «eso se queda en casa» hacen que contar tenga un costo alto. La niña puede temer quedar expuesta frente a su comunidad o su escuela."}, {"h": "Factores institucionales", "t": "Servicios que no escuchan, adultos que minimizan o procesos que obligan a repetir el relato pueden desalentar que la persona vuelva a hablar. Esto también es parte del silencio."}], "destacado": "La pregunta cambia: de por qué no lo dijo, a qué hizo posible decirlo."}, {"bloque": "S1.4", "tipo": "texto", "titulo": "Desarrollo y variabilidad: el malestar no se ve igual a todas las edades", "items": [{"h": "Primera infancia", "t": "Pueden aparecer cambios en el sueño, la alimentación, el juego o el apego. Por ejemplo, miedo intenso a separarse de un cuidador o regresiones en el control de esfínteres. Son señales inespecíficas que también se asocian a muchas otras situaciones."}, {"h": "Edad escolar", "t": "Puede haber dificultades de concentración, cambios en el rendimiento, ansiedad al ir a la escuela, quejas somáticas o conductas agresivas o retraídas. Muchas veces se interpretan como problemas de conducta si no se mira la historia."}, {"h": "Adolescencia", "t": "Pueden aparecer autolesiones, consumo de sustancias, cambios bruscos de amistades, conductas sexuales inapropiadas para la edad o dificultad para confiar. Algunas se leen como rebeldía si no se conoce el contexto."}], "destacado": "Estas manifestaciones son posibles, no obligatorias, y nunca son específicas de abuso."}, {"bloque": "S1.4", "tipo": "tarjetas", "titulo": "Seis dominios donde puede verse el malestar", "intro": "Revisar estos dominios evita olvidar alguno. No se usan para confirmar un abuso, sino para entender cómo está la niña o el niño en su vida diaria.", "items": [{"h": "Emocional", "t": "Tristeza persistente, irritabilidad, miedo intenso, vergüenza o culpa, o cambios bruscos de ánimo que no tienen una explicación evidente."}, {"h": "Conductual", "t": "Cambios en el juego, en la alimentación, en el control de impulsos o en conductas sexuales que no corresponden a su edad."}, {"h": "Cognitivo", "t": "Dificultades de atención o memoria, o una forma de ver el mundo que se vuelve amenazante, muy negativa o muy confusa."}, {"h": "Somático", "t": "Dolores de cabeza o abdominales, molestias genitales o urinarias sin causa médica clara, o cansancio constante. Siempre requieren valoración médica."}, {"h": "Relacional", "t": "Dificultad para confiar, para sostener amistades o para aceptar límites. También puede haber cambios en el apego con sus cuidadores."}, {"h": "Escolar", "t": "Baja en calificaciones, inasistencias, conflictos con compañeros o pérdida de interés en actividades que antes disfrutaba."}]}, {"bloque": "S1.4", "tipo": "texto", "titulo": "Por qué ninguna señal aislada confirma ni descarta un abuso", "items": [{"h": "Las señales se superponen", "t": "Un mismo signo puede deberse a un duelo, a una separación familiar, al acoso escolar, a una enfermedad, a la ansiedad o a problemas de sueño. Sin contexto, la lectura es insegura."}, {"h": "Puede no haber señales visibles", "t": "Muchas niñas y niños no muestran cambios evidentes, y otros los muestran años después. Que no haya señales no prueba que nada haya pasado."}, {"h": "El riesgo de sobreinterpretar", "t": "Tratar un síntoma como prueba puede llevar a una conclusión falsa, a acusar a alguien injustamente o a que el niño sienta que su malestar no se entiende."}], "destacado": "Lo que podemos hacer es registrar, observar a lo largo del tiempo y evaluar. No concluir."}, {"bloque": "S1.4", "tipo": "caso", "titulo": "Caso ficticio: Mateo, 14 años", "intro": "Mateo tiene 14 años. En los últimos meses sus calificaciones bajaron, se alejó de sus amigos, duerme poco y ya no quiere ir a entrenar. No ha hecho ninguna revelación y nadie sabe de situaciones de abuso.", "items": [{"h": "Pregunta 1", "t": "¿Qué indicadores son específicos de abuso?"}, {"h": "Pregunta 2", "t": "¿Qué harías en la consulta, y qué no harías?"}]}, {"bloque": "S1.5", "tipo": "texto", "titulo": "Cinco principios de un abordaje sensible al trauma", "items": [{"h": "Seguridad", "t": "El ambiente debe sentirse predecible y libre de amenazas. Explicar quién estará presente, dónde y por cuánto tiempo ayuda a que la niña o el niño se sienta más seguro."}, {"h": "Previsibilidad y claridad", "t": "Decir qué va a pasar, cuándo y qué puede o no puede esperar. Evita sorpresas y promesas que no podrás cumplir."}, {"h": "Validación", "t": "Creer en la experiencia del niño no obliga a confirmar hechos. Puedes decir: «Lo que me cuentas es importante, y no es tu culpa»."}, {"h": "Ritmo y control", "t": "La persona decide cuánto contar y cuándo. Ofrecer opciones apropiadas para su edad, como dibujar, jugar, hablar o escribir, reduce la sensación de estar sin control."}, {"h": "Colaboración", "t": "El trabajo se hace con la niña o el niño y, cuando es seguro, con sus cuidadores. El profesional acompaña; no decide por ella ni por él."}], "destacado": "La seguridad emocional y física van primero. La información viene después."}, {"bloque": "S1.5", "tipo": "contraste", "titulo": "Acompañar no es entrevistar: dos tareas distintas", "items": [{"h": "Atención clínica", "t": "Busca el bienestar, evaluar síntomas y planear apoyos. La persona puede contar lo que quiera, cuando quiera, y el profesional registra solo lo necesario para cuidarla. No se buscan detalles para comprobar nada.", "ej": "«Cuéntame lo que quieras. Podemos parar cuando lo necesites.»"}, {"h": "Entrevista forense", "t": "Busca reconstruir hechos para un proceso investigativo o judicial. Sigue protocolos específicos y la realizan profesionales entrenados para ello. No se hace desde la atención clínica, y mezclarlas puede afectar ambos procesos.", "ej": "Preguntas abiertas, sin sugerir respuestas, con el registro literal de lo que se dice."}], "destacado": "Si la atención clínica se vuelve interrogatorio, puede dañar a la persona y también un posible proceso de investigación."}, {"bloque": "S1.5", "tipo": "tarjetas", "titulo": "Qué evitar, aunque se haga con buena intención", "items": [{"h": "Preguntas sugestivas", "t": "Preguntas como «¿Te tocó?» o «¿Fue tu papá?» instalan respuestas y pueden contaminar el relato. Son cerradas y sugieren la respuesta que el adulto espera."}, {"h": "Detalles innecesarios", "t": "Pedir que describa lo ocurrido, con cuerpo, lugar o fechas, no ayuda a la atención y puede obligarle a revivirlo."}, {"h": "Promesas de secreto", "t": "Decir «esto no se lo digo a nadie» es una promesa que quizá no se pueda cumplir si hay riesgo. Es mejor explicar los límites desde el inicio."}, {"h": "Exigir un relato", "t": "Pedir que lo repita para «estar seguros», o que lo cuente a varias personas, aumenta la carga y el riesgo de revictimización."}], "destacado": "Cada pregunta extra es una exposición extra. Pregunta solo lo necesario para proteger."}, {"bloque": "S1.6", "tipo": "caso", "titulo": "Caso ficticio: Valeria, 9 años", "intro": "Valeria tiene 9 años. Llega a consulta por dolor abdominal recurrente, enuresis secundaria y baja escolar. Vive con su mamá, con la pareja de su mamá y con su abuela. Hasta ahora no ha hecho ninguna revelación.", "items": [{"h": "Pregunta 1", "t": "¿Qué separarías como dato, observación e hipótesis?"}, {"h": "Pregunta 2", "t": "¿Qué información falta antes de formular objetivos?"}]}, {"bloque": "S1.7", "tipo": "tarjetas", "titulo": "Síntesis: cinco ideas para llevarte de esta sesión", "items": [{"h": "La responsabilidad es de quien agrede", "t": "El silencio y las reacciones de la niña se entienden dentro de una relación desigual. No son una falla suya."}, {"h": "Ningún signo aislado es prueba", "t": "Una señal no confirma ni descarta un abuso. Lo que importa es el patrón, el contexto y el tiempo."}, {"h": "Dato no es hipótesis", "t": "Separar lo reportado, lo observado y lo supuesto evita conclusiones prematuras y decisiones equivocadas."}, {"h": "La seguridad y el vínculo van primero", "t": "Antes de cualquier otra tarea, la persona necesita sentirse segura y acompañada por alguien que la escuche."}, {"h": "Atender no es investigar", "t": "Acompañar y evaluar no exige reconstruir hechos. Esa tarea corresponde a otras instancias y procedimientos."}], "destacado": "En la sesión 2 veremos qué hacer cuando alguien decide contar."}]}, {"n": 2, "kicker": "Sesión 2 · 3 horas · bloques S2.1 a S2.7", "titulo": "Violencia sexual infantil: revelación, escucha y cuidadores protectores", "subtitulo": "Ejemplos narrados, no dramatizados. Material educativo: no sustituye protocolos institucionales ni supervisión clínica.", "pausa": "Pausa de 10 minutos entre S2.3 y S2.4. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "Esta sesión trata de lo que ocurre cuando una niña, un niño o un adolescente decide contar lo que vive. La forma en que un adulto responde en ese momento puede abrir la puerta a la protección o cerrarla.", "items": [{"h": "Respuesta inicial", "t": "Cómo escuchar y validar sin revictimizar, y qué decir en los primeros minutos."}, {"h": "Apoyo y no investigación", "t": "Qué diferencia hay entre acompañar a alguien y reconstruir los hechos."}, {"h": "Cuidadores protectores", "t": "Cómo identificar a los adultos que pueden proteger, y cómo evaluar a los que no pueden."}, {"h": "Objetivos iniciales", "t": "Cómo formular un primer plan sin pedir un relato detallado."}]}, {"bloque": "S2.1", "tipo": "tarjetas", "titulo": "Lo esencial de la sesión 1, que sostiene esta sesión", "items": [{"h": "La responsabilidad es de quien agrede", "t": "Esto debe quedar claro en toda respuesta. Nunca se le pide a la niña que justifique lo que pasó."}, {"h": "Dato, observación e hipótesis", "t": "Lo que la persona dice, lo que se observa y lo que aún se supone deben registrarse por separado."}, {"h": "Seguridad y vínculo primero", "t": "Antes de cualquier otra tarea, la persona necesita sentirse segura y acompañada."}]}, {"bloque": "S2.2", "tipo": "texto", "titulo": "Vergüenza y culpa: cómo se instalan después de una experiencia de violencia sexual", "items": [{"h": "Vergüenza", "t": "La vergüenza dice «algo está mal en mí». Lleva a esconderse, a no mirar a los demás y a pensar que, si se supiera, nadie la querría. Por eso el silencio suele ser una forma de protegerse de sentirse expuesta."}, {"h": "Culpa", "t": "Muchas personas sienten que pudieron evitar lo ocurrido, aunque no tuvieron ninguna responsabilidad. La culpa se alimenta cuando los adultos cercanos preguntan por qué no se fue o por qué no lo dijo antes."}], "destacado": "La culpa que siente una víctima no corresponde a lo que hizo. Surge de cómo sobrevive a una relación de poder."}, {"bloque": "S2.2", "tipo": "texto", "titulo": "Miedo, indefensión y seguridad en los vínculos", "items": [{"h": "Miedo", "t": "El miedo puede ser constante o aparecer ante recordatorios. En niñas y niños puede verse como ansiedad al separarse de un adulto, al quedarse solos o al estar cerca de personas que se parecen a quien agredió."}, {"h": "Indefensión", "t": "Es la sensación de que nada de lo que se haga cambia el resultado. Puede llevar a someterse, a no pedir ayuda o a quedarse paralizada en situaciones nuevas."}, {"h": "Seguridad interpersonal", "t": "La confianza en otras personas puede dañarse. La persona puede pensar que nadie la protege, o que todos quieren algo de ella. Esto dificulta pedir ayuda incluso cuando la necesita."}], "destacado": "Estas respuestas son comprensibles dentro de una experiencia de amenaza real. No son una falla de la persona."}, {"bloque": "S2.2", "tipo": "texto", "titulo": "Imagen corporal, límites y vínculos: áreas que conviene observar", "items": [{"h": "Imagen corporal", "t": "El cuerpo puede sentirse ajeno, sucio o peligroso. Algunas personas evitan mirarse, cambian su forma de vestir o rechazan ciertos cuidados físicos. Estas conductas pueden tener muchas explicaciones."}, {"h": "Límites personales", "t": "Puede haber dificultad para decir no, o al contrario, dificultad para sostener límites con cualquiera. Ambas respuestas pueden ser formas de intentar recuperar control."}, {"h": "Confianza y vínculos", "t": "Las relaciones afectivas pueden volverse intensas, distantes o confusas. El apego con cuidadores es un terreno delicado que conviene observar con cuidado, sin conclusiones apresuradas."}], "destacado": "Cada persona responde de forma distinta. Estas áreas se evalúan, no se generalizan."}, {"bloque": "S2.3", "tipo": "texto", "titulo": "Qué es una revelación y por qué suele ser gradual", "items": [{"h": "Contar no es un acto único", "t": "Muchas personas dan pistas antes de decir algo directamente: una frase, un cambio de tema, una pregunta extraña. La revelación puede ser espontánea, parcial o gradual, y puede retractarse después."}, {"h": "A quién se le cuenta", "t": "Se cuenta a quien se percibe como seguro: una maestra, una enfermera, una amiga o un profesional. A veces la persona lo cuenta por accidente, durante otra conversación."}, {"h": "Lo que el adulto hace en ese momento", "t": "La primera respuesta suele definir si la persona vuelve a hablar. Un adulto tranquilo y creíble abre la puerta para seguir. Un adulto que se alarma o que minimiza la cierra."}], "destacado": "La forma en que recibimos un relato puede influir en si la persona vuelve a buscar ayuda."}, {"bloque": "S2.3", "tipo": "flujo", "titulo": "Los primeros minutos: escuchar y responder en cuatro pasos", "items": [{"h": "Calma y gratitud", "t": "Responde con calma y agradece la confianza: «Gracias por contármelo. Sé que no fue fácil.» Mantén un tono tranquilo, aunque te alarme lo que escuchas."}, {"h": "Creer y validar", "t": "Di que le crees y que lo que siente es válido. No hace falta conocer los detalles para validar la experiencia ni para respetarla."}, {"h": "Seguridad inmediata", "t": "Pregunta lo necesario para saber si hay peligro ahora o contacto con la persona señalada. Si hay riesgo inmediato, activa el protocolo de urgencia."}, {"h": "Límites y próximos pasos", "t": "Explica con palabras sencillas qué harás a continuación y quién más tendría que saberlo, para que no sea una sorpresa."}], "destacado": "Preguntar lo necesario para la seguridad es distinto de investigar. No pidas reconstrucciones del hecho."}, {"bloque": "S2.3", "tipo": "texto", "titulo": "Confidencialidad con límites: cómo explicarla sin prometer lo imposible", "items": [{"h": "Qué significa", "t": "No se promete secreto absoluto. Se explica que, si hay riesgo de daño, habrá que compartir información con quien pueda proteger a la persona. Esto se dice desde el inicio, no a mitad de la conversación."}, {"h": "Cómo decirlo", "t": "Por ejemplo: «Lo que me cuentas lo voy a cuidar. Solo lo compartiría si estás en peligro, y en ese caso buscaría ayuda para que estés segura.»"}, {"h": "Qué no decir", "t": "«No se lo diré a nadie» o «todo va a salir bien». Son promesas que quizá no se puedan cumplir y que pueden romper la confianza más adelante."}], "destacado": "Una promesa incumplida hace más daño que un límite explicado con claridad."}, {"bloque": "S2.4", "tipo": "contraste", "titulo": "Protege o revictimiza: una intención buena puede sonar muy distinta", "items": [{"h": "Respuestas que protegen", "t": "Validan, aclaran el siguiente paso y mantienen el foco en la persona y en su seguridad.", "ej": "«Gracias por contármelo.» · «Te creo, y no es tu culpa.» · «Vamos a buscar ayuda para que estés segura.»"}, {"h": "Respuestas que revictimizan", "t": "Ponen en duda el relato, buscan detalles innecesarios o hacen sentir responsable a la persona.", "ej": "«¿Estás segura de lo que dices?» · «¿Por qué no lo dijiste antes?» · «Cuéntame otra vez, con todos los detalles.»"}], "destacado": "Quienes dicen estas frases casi nunca quieren dañar. Por eso conviene aprender otras."}, {"bloque": "S2.4", "tipo": "texto", "titulo": "La revictimización también ocurre en las instituciones", "items": [{"h": "Repetir el relato", "t": "Cada vez que alguien pide a la niña que cuente lo ocurrido, la experiencia se vuelve a abrir. Coordinar entre servicios evita pedirle lo mismo varias veces a personas distintas."}, {"h": "Exposición innecesaria", "t": "Hablar de su caso frente a personas que no lo necesitan, o en espacios sin privacidad, la expone a comentarios, burlas o estigma, sobre todo en la escuela."}, {"h": "Silencio y falta de seguimiento", "t": "Dar una primera respuesta y después no volver a saber de la persona deja la sensación de que nadie se hace responsable de lo que pasó."}], "destacado": "Proteger también significa que el sistema trabaje de forma coordinada, con información mínima y responsables claros."}, {"bloque": "S2.5", "tipo": "tarjetas", "titulo": "Qué hace protector a un cuidador", "items": [{"h": "Ofrece seguridad", "t": "Su presencia es predecible, responde cuando la niña pide ayuda y pone límites a quien le hace daño."}, {"h": "Cree y acompaña", "t": "Escucha sin desacreditar y acepta que el malestar del niño es real, aunque no entienda todo lo que pasó."}, {"h": "Busca apoyo", "t": "Se acerca a los servicios, sigue las indicaciones y tolera la intervención sin minimizar lo que ocurre."}, {"h": "Tiene capacidad", "t": "Su propia situación, como salud, consumo, violencia en la pareja o falta de recursos, le permite sostener ese papel."}], "destacado": "Ser madre, padre o abuela no garantiza que alguien sea protector. Se evalúa caso por caso."}, {"bloque": "S2.5", "tipo": "texto", "titulo": "Otros adultos implicados y la evaluación del riesgo", "items": [{"h": "Quién puede representar riesgo", "t": "Una pareja, un familiar o cualquier adulto con acceso al niño puede ser una fuente de riesgo, aunque no sea quien agredió. También lo es quien minimiza o protege a la persona señalada."}, {"h": "Cómo se evalúa", "t": "Con información de varias fuentes: lo que dice la niña, lo que observan los servicios, la historia de la familia y la seguridad actual. Una sola conversación no alcanza para evaluar el riesgo."}, {"h": "Qué hacer si hay duda", "t": "Antes de informar a un adulto, consulta el protocolo aplicable y pregúntate si ese paso puede aumentar el riesgo para la niña."}], "destacado": "Informar a una familia sin evaluar el riesgo puede poner al niño en más peligro."}, {"bloque": "S2.5", "tipo": "texto", "titulo": "Intervenir con cuidadores: cuándo, cómo y con qué límites", "items": [{"h": "Cuándo es apropiado", "t": "Cuando el cuidador es protector, puede participar en el plan de seguridad y apoyo, y su participación no pone en riesgo a la niña o al niño."}, {"h": "Cómo se hace", "t": "Con psicoeducación sobre el malestar infantil, orientación para responder a los síntomas y espacios para que el cuidador exprese sus propias reacciones, que también son intensas."}, {"h": "Con qué límites", "t": "No se les pide que confronten a la persona señalada ni que investiguen. Su papel es acompañar y proteger dentro de lo que es seguro para todos."}], "destacado": "El cuidador también necesita apoyo. Acompañarlo es parte de proteger a la niña o al niño."}, {"bloque": "S2.6", "tipo": "caso", "titulo": "Viñeta: Valeria le cuenta algo a la enfermera escolar", "intro": "Valeria tiene 9 años. Un día le dice a la enfermera de su escuela que hay algo que le pasa en casa y que no quiere que nadie lo sepa. Más tarde, la enfermera informa a la mamá, y ella responde: «eso no puede ser».", "items": [{"h": "Pregunta 1", "t": "¿Qué haces en los primeros minutos con Valeria?"}, {"h": "Pregunta 2", "t": "¿Cómo te preparas antes de hablar con la mamá, y qué te preocupa?"}]}, {"bloque": "S2.6", "tipo": "caso", "titulo": "Caso ficticio: un comentario en el recreo", "intro": "Un niño de 8 años le dice a su maestra, en el recreo: «mi primo me pide que no le diga a nadie». Está nervioso y no quiere hablar más de eso.", "items": [{"h": "Pregunta 1", "t": "¿Cómo respondes en ese momento?"}, {"h": "Pregunta 2", "t": "¿Qué no debes hacer?"}]}, {"bloque": "S2.7", "tipo": "flujo", "titulo": "Del relato a la protección: el camino de la primera respuesta", "items": [{"h": "Escuchar", "t": "Dejar que la persona cuente lo que puede, al ritmo que puede, sin interrumpir ni dirigir."}, {"h": "Validar", "t": "Creer en la experiencia y en la emoción, y decirlo con palabras claras."}, {"h": "Proteger", "t": "Evaluar la seguridad inmediata y activar la urgencia cuando sea necesario."}, {"h": "Coordinar", "t": "Compartir lo mínimo necesario con quien corresponde, y dar seguimiento al caso."}], "destacado": "Transición: la sesión 3 trata de la evaluación y del tratamiento de los síntomas postraumáticos."}]}, {"n": 3, "kicker": "Sesión 3 · 3 horas · bloques S3.1 a S3.7", "titulo": "TEPT infantil y trauma complejo: manifestaciones, intervención y seguimiento", "subtitulo": "Contenido sensible. No se piden recuerdos ni se presentan técnicas de exposición para hacer en casa. Material educativo, no sustituye evaluación clínica.", "pausa": "Pausa de 10 minutos entre S3.3 y S3.4. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "Esta sesión trata de cómo se ven los síntomas postraumáticos en la infancia, cómo distinguirlos de otras respuestas y cómo elegir, adaptar y seguir una intervención. La idea central es que un síntoma no es un diagnóstico, y que el diagnóstico exige evaluación.", "items": [{"h": "Manifestaciones", "t": "Qué grupos de síntomas describen el TEPT y cómo se expresan en cada etapa de la infancia."}, {"h": "Curso y diferenciación", "t": "Cómo distinguir una respuesta adaptativa a un peligro de síntomas que persisten, y qué otras explicaciones hay que descartar."}, {"h": "Recordatorios y evitación", "t": "Qué dispara la respuesta de alarma y cómo se acompaña la vida diaria sin forzar exposiciones."}, {"h": "Intervención y seguimiento", "t": "Qué principios guían la elección de un tratamiento y qué indicadores permiten saber si funciona."}]}, {"bloque": "S3.1", "tipo": "texto", "titulo": "Cómo leer síntomas sin convertirlos en diagnóstico", "items": [{"h": "Un ejemplo no sustituye la evaluación", "t": "Las descripciones de esta sesión son orientativas. Un mismo síntoma puede tener causas distintas, y el diagnóstico se construye con una evaluación individual, con varias fuentes de información."}, {"h": "El contenido es sensible", "t": "No se piden recuerdos ni se describen escenas. Si el tema toca experiencias personales de quien escucha, puede pausar, salir o buscar apoyo en cualquier momento."}, {"h": "Qué buscamos", "t": "Comprender qué le pasa a la niña o al niño, qué lo protege y qué ajustes necesita el plan. No buscamos etiquetar."}], "destacado": "Un síntoma orienta una pregunta. Solo una evaluación completa permite responderla."}, {"bloque": "S3.2", "tipo": "tarjetas", "titulo": "Cuatro grupos de síntomas postraumáticos", "intro": "Los sistemas diagnósticos agrupan los síntomas postraumáticos en categorías parecidas, aunque los criterios difieren en detalles. Para que un cuadro sea TEPT se requiere evaluación de criterios, duración y afectación del funcionamiento.", "items": [{"h": "Reexperimentación", "t": "Recuerdos intrusivos, pesadillas y juego repetitivo con temas que recuerdan la experiencia, o malestar intenso ante recordatorios."}, {"h": "Evitación", "t": "Rechazo de lugares, personas, actividades o pensamientos asociados, que puede limitar la vida diaria."}, {"h": "Cambios negativos en ánimo y pensamiento", "t": "Culpa, vergüenza, desesperanza, desconexión emocional o pérdida de interés en actividades que antes gustaban."}, {"h": "Hiperactivación", "t": "Sobresalto, irritabilidad, dificultad para dormir, problemas de concentración o estado de alerta constante."}], "destacado": "Para hablar de TEPT se necesita más que un síntoma: criterios, duración e interferencia en la vida diaria."}, {"bloque": "S3.2", "tipo": "texto", "titulo": "Cómo se expresan estos síntomas en cada etapa de la infancia", "items": [{"h": "Primera infancia", "t": "Puede verse en juego repetitivo, regresiones, miedo a separarse de un cuidador o pesadillas sin contenido claro. Los niños pequeños muestran el malestar en el cuerpo y en la conducta más que en palabras."}, {"h": "Edad escolar", "t": "Puede verse en dificultades de concentración, quejas somáticas, retraimiento, irritabilidad o conflictos con compañeros. A veces el rendimiento escolar es la primera señal que nota un adulto."}, {"h": "Adolescencia", "t": "Puede verse en evitación de personas o lugares, consumo de sustancias, conductas de riesgo, culpa intensa o una autocrítica muy fuerte. Puede parecerse a un cuadro depresivo o ansioso."}], "destacado": "El juego repetitivo puede ser una señal que merece evaluación, pero no es una prueba por sí misma."}, {"bloque": "S3.2", "tipo": "texto", "titulo": "Síntomas que se confunden: cuándo mirar más allá", "items": [{"h": "Ansiedad", "t": "La ansiedad generalizada o la ansiedad de separación pueden tener síntomas parecidos: preocupación, miedo, inquietud y dificultad para dormir."}, {"h": "Depresión", "t": "El ánimo bajo, la pérdida de interés, la culpa y la fatiga pueden aparecer en el TEPT y en la depresión. Diferenciarlas requiere mirar la historia y el curso de los síntomas."}, {"h": "Déficit de atención e hiperactividad", "t": "La dificultad de concentración y la inquietud pueden coincidir con síntomas de trauma o tener un origen propio. Ambas situaciones necesitan valorarse por separado."}, {"h": "Causas médicas y duelo", "t": "Dolor, problemas de sueño o cambios de conducta pueden tener causas médicas, o responder a una pérdida o a una mudanza que no tenga relación con el trauma."}], "destacado": "El diagnóstico diferencial es parte del trabajo clínico, no un trámite previo."}, {"bloque": "S3.3", "tipo": "texto", "titulo": "Respuesta adaptativa frente a síntomas que persisten", "items": [{"h": "Respuesta adaptativa", "t": "Es la alerta y la evitación proporcionales a una amenaza real y actual. Tienen sentido: protegen. Si una niña se sobresalta al escuchar pasos en un pasillo donde hay alguien que la amenaza, esa reacción es adaptativa."}, {"h": "Síntomas que persisten", "t": "Ocurren cuando la amenaza ya cesó pero la respuesta sigue, dura semanas o meses e interfiere con la escuela, el sueño o los vínculos. Este patrón es el que se evalúa como posible TEPT."}, {"h": "La pregunta que va primero", "t": "Antes de decidir si un síntoma es adaptativo o persistente, hay que saber si la amenaza sigue presente: si hay contacto con la persona señalada, si cambió la vivienda o si el cuidador está disponible."}], "destacado": "Una niña que se sobresalta en casa de quien le hizo daño reacciona a una amenaza real. Una que se sobresalta después de mudarse a un lugar seguro necesita otra mirada."}, {"bloque": "S3.3", "tipo": "texto", "titulo": "El curso en el tiempo: mejoría, recaídas y exposición continua", "items": [{"h": "El curso puede fluctuar", "t": "Es frecuente que los síntomas mejoren y reaparezcan, sobre todo ante recordatorios, cambios de vida o nuevas situaciones de estrés. Una recaída no siempre significa que el tratamiento fracasó."}, {"h": "La exposición continua mantiene la alarma", "t": "Si la niña sigue en contacto con la persona señalada, o vive con un cuidador que no la protege, la alarma se mantiene por razones reales. Los síntomas no se van porque el entorno sigue siendo amenazante."}, {"h": "Cómo se evalúa el curso", "t": "Revisando los síntomas en el tiempo, con fechas, frecuencia e intensidad. Una sola evaluación no muestra si algo está mejorando o empeorando."}], "destacado": "Un cambio sin contexto puede deberse a una mejoría o a una nueva amenaza. Ambas posibilidades se revisan."}, {"bloque": "S3.3", "tipo": "caso", "titulo": "Caso ficticio: Valeria, tres meses después", "intro": "Tres meses después de su primera consulta, Valeria tiene pesadillas, se sobresalta con facilidad y evita algunas actividades de cuidado personal. Repite el mismo juego una y otra vez. En casa, las cosas no han cambiado todavía.", "items": [{"h": "Pregunta 1", "t": "¿Esto es TEPT, una respuesta adaptativa o trauma complejo?"}, {"h": "Pregunta 2", "t": "¿Qué necesitas saber antes de decidir?"}]}, {"bloque": "S3.4", "tipo": "texto", "titulo": "Recordatorios: qué los dispara y cómo se acompañan", "items": [{"h": "Recordatorios internos", "t": "Sensaciones corporales, emociones, pensamientos o imágenes que pueden activar el recuerdo sin que la persona lo decida."}, {"h": "Recordatorios externos", "t": "Sonidos, olores, lugares, personas parecidas, horas del día o situaciones de cuidado. Cada persona tiene los suyos, y muchas veces no los reconoce hasta que aparecen."}, {"h": "Cómo se acompaña", "t": "Ayudar a identificar los disparadores de forma gradual y sin forzar el contacto. Enseñar formas de calmarse, como respirar, anclarse en el presente o hacer una pausa, y crear rutinas predecibles."}], "destacado": "Identificar un disparador no obliga a enfrentarlo. El primer paso es que la persona sienta que puede regular lo que le pasa."}, {"bloque": "S3.4", "tipo": "texto", "titulo": "Pesadillas, sueño y evitación en la vida diaria", "items": [{"h": "Sueño", "t": "Las pesadillas recurrentes y el sueño fragmentado afectan la atención, el ánimo y la tolerancia a la frustración. Una rutina previsible antes de dormir ayuda, y conviene revisarla con la familia."}, {"h": "Evitación cotidiana", "t": "Evitar un lugar, cambiar de ruta o rechazar ciertas actividades de cuidado personal puede ser una forma de protegerse. Se respeta mientras se construye seguridad, sin forzar la situación."}, {"h": "Lo que no conviene hacer", "t": "Obligar a la niña a enfrentar lo que evita, pedirle que describa lo ocurrido para «superarlo» o presentar la exposición como una técnica de autoayuda."}], "destacado": "La evitación ayuda a sobrevivir a corto plazo. El trabajo clínico busca ampliar opciones, sin forzar."}, {"bloque": "S3.5", "tipo": "texto", "titulo": "Principios comunes de cualquier intervención en la infancia", "items": [{"h": "Adecuación al desarrollo", "t": "El lenguaje, el juego, el ritmo y las herramientas deben corresponder a la edad. Un tratamiento pensado para adultos no debe aplicarse a un niño sin adaptarlo."}, {"h": "Seguridad antes que el recuerdo", "t": "La regulación emocional y la seguridad actual se trabajan antes de elaborar la experiencia traumática. Si no hay estabilidad, elaborar el recuerdo puede desbordar a la niña."}, {"h": "Participación de cuidadores cuando es segura", "t": "Los cuidadores protectores pueden aprender a apoyar, validar y responder al malestar. Cuando no son seguros, la intervención se organiza sin ellos y con otros apoyos."}, {"h": "Evaluación continua", "t": "Se revisa de forma periódica si la intervención ayuda, si hay riesgos nuevos y si el plan sigue siendo adecuado para la edad y el contexto."}], "destacado": "La elección del tratamiento depende de lo que la niña puede usar hoy, no de lo que se usó en otro caso."}, {"bloque": "S3.5", "tipo": "texto", "titulo": "La TCC focalizada en trauma: qué es y a quién se recomienda", "items": [{"h": "Qué es", "t": "Es una intervención estructurada y manualizada, de tipo cognitivo-conductual, pensada para síntomas relacionados con el trauma. Incluye psicoeducación, habilidades de regulación emocional y trabajo sobre pensamientos y creencias ligados a la experiencia."}, {"h": "Cómo se organiza", "t": "La elaboración de la experiencia traumática se hace de forma gradual y segura, solo cuando la persona cuenta con habilidades para regularse. En niñas y niños suele involucrar a los cuidadores."}, {"h": "A quién se recomienda", "t": "Guías como NICE NG116 la recomiendan para niñas, niños y adolescentes con síntomas clínicamente importantes o con TEPT, adaptada al desarrollo y entregada por profesionales formados y supervisados."}], "destacado": "Es un tratamiento que se aprende con formación y supervisión. Esta clase lo presenta; no enseña a aplicarlo."}, {"bloque": "S3.5", "tipo": "texto", "titulo": "Cómo elegir y adaptar: edad, contexto y capacidad", "items": [{"h": "Edad y etapa del desarrollo", "t": "Determinan el lenguaje, el formato y el ritmo. Una intervención puede ser útil en la adolescencia y necesitar cambios importantes en la primera infancia."}, {"h": "Seguridad y cuidado", "t": "Quién cuida a la niña, dónde vive y si hay contacto con la persona señalada cambian lo que es posible y seguro hacer."}, {"h": "Preferencias, familia y capacidad del equipo", "t": "Se consideran las preferencias de la niña y de su familia, la formación del equipo y la disponibilidad de supervisión. Sin competencia suficiente, conviene derivar."}, {"h": "Cuando no hay respuesta", "t": "Antes de decir que una intervención no funciona, se revisa la evaluación, el contexto, la alianza con la niña y la seguridad."}], "destacado": "La decisión no es sobre una técnica, sino sobre lo que esa niña puede usar hoy y en qué entorno."}, {"bloque": "S3.6", "tipo": "tarjetas", "titulo": "Indicadores para seguir el caso", "intro": "Un buen seguimiento combina lo que observa el equipo con lo que dicen la niña, el niño y su cuidador protector. Conviene revisar estos indicadores en intervalos definidos desde el inicio.", "items": [{"h": "Seguridad", "t": "¿Hay contacto con la persona señalada? ¿La niña se siente a salvo en casa, en la escuela y en los trayectos?"}, {"h": "Síntomas", "t": "Frecuencia, intensidad y duración de pesadillas, sobresaltos, evitación y cambios de ánimo."}, {"h": "Regulación", "t": "Cómo se calma cuando algo le recuerda la experiencia, y con qué frecuencia aparecen crisis."}, {"h": "Vínculos", "t": "Relación con cuidadores, amistades y adultos de referencia, y cambios en la confianza."}, {"h": "Escuela", "t": "Asistencia, rendimiento y relación con compañeros y maestros."}, {"h": "Funcionamiento", "t": "Juego, actividades, autonomía en el cuidado personal y participación en lo que antes disfrutaba."}]}, {"bloque": "S3.6", "tipo": "texto", "titulo": "Mejoría, fluctuación y falta de respuesta no son lo mismo", "items": [{"h": "Mejoría sostenida", "t": "Los síntomas disminuyen y se mantienen más bajos en el tiempo, la seguridad se fortalece y la vida diaria se recupera."}, {"h": "Fluctuación esperable", "t": "Es normal que haya días peores, sobre todo ante recordatorios o cambios. Una subida aislada no indica necesariamente que el plan falló."}, {"h": "Falta de respuesta", "t": "Cuando no hay cambios después de un tiempo razonable, conviene revisar la evaluación, la adecuación del plan, la alianza y la seguridad, y considerar otras explicaciones."}, {"h": "Exposición continuada a amenazas", "t": "Si la amenaza sigue presente, la prioridad es la protección. Ninguna intervención psicológica compensa un entorno que sigue haciendo daño."}], "destacado": "Antes de decir que una intervención no funciona, revisa si la niña está segura."}, {"bloque": "S3.7", "tipo": "flujo", "titulo": "Evaluar, elegir, adaptar y seguir: la ruta de la sesión", "items": [{"h": "Evaluar", "t": "Síntomas, historia, curso y seguridad, con varias fuentes de información y una mirada de diagnóstico diferencial."}, {"h": "Elegir", "t": "Qué intervención corresponde, según la edad, el contexto, la seguridad y la competencia del equipo."}, {"h": "Adaptar", "t": "Ajustar el lenguaje, el ritmo, la participación de cuidadores y las metas a la persona concreta."}, {"h": "Seguir", "t": "Revisar indicadores en intervalos definidos, y ajustar el plan cuando lo muestren los datos."}], "destacado": "Transición: la sesión 4 trata de protección, contexto, ética y la integración de un caso complejo."}]}, {"n": 4, "kicker": "Sesión 4 · 3 horas · bloques S4.1 a S4.8", "titulo": "Protección infantil, contexto, ética e integración clínica", "subtitulo": "Revisión educativa del marco mexicano. No sustituye asesoría jurídica, protocolos institucionales ni procedimientos de emergencia.", "pausa": "Pausa de 10 minutos entre S4.4 y S4.5. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "Esta sesión reúne todo lo anterior. Una niña o un niño no vive en un expediente: vive en una casa, una escuela, una comunidad y un sistema que puede protegerla o agotarla. Aquí aprendemos a pensar el caso completo y a decidir con responsabilidad.", "items": [{"h": "Contexto y seguridad", "t": "Cómo leer el entorno y valorar el riesgo actual sin convertir la evaluación en una investigación."}, {"h": "Planificación y coordinación", "t": "Cómo armar un plan con responsables claros, y con qué actores se trabaja."}, {"h": "Marco legal y ética", "t": "Qué dice el marco mexicano de derechos, qué verificar en cada caso y dónde terminan los límites del rol clínico."}, {"h": "Integración", "t": "Cómo formular un caso complejo, priorizar la protección y definir objetivos y seguimiento."}]}, {"bloque": "S4.1", "tipo": "texto", "titulo": "Protección, contexto y límites del rol clínico", "items": [{"h": "Atención, protección y justicia son tareas distintas", "t": "La atención clínica busca el bienestar y la recuperación. La protección busca que la niña o el niño esté seguro. La justicia determina responsabilidades. Cada una tiene actores, tiempos y procedimientos propios."}, {"h": "Esta clase es educativa", "t": "Presenta un marco general para pensar los casos. No es asesoría jurídica ni sustituye la consulta con quien conoce la ley vigente de tu entidad y tu institución."}, {"h": "No sustituye la urgencia", "t": "Si hay riesgo inmediato, se activa el protocolo de urgencia que corresponde. Una clase no puede reemplazar ese procedimiento."}], "destacado": "Cada profesional conoce el límite de su rol. Reconocerlo protege a la niña y al propio profesional."}, {"bloque": "S4.2", "tipo": "tarjetas", "titulo": "Capas del contexto que rodean a una niña o un niño", "items": [{"h": "Hogar", "t": "Es el primer espacio de seguridad o de riesgo. Incluye a quienes viven con la niña y a quienes la visitan o la cuidan."}, {"h": "Escuela", "t": "Ofrece rutina, adultos de referencia y un espacio de observación. También puede ser un lugar de exposición o de estigma."}, {"h": "Comunidad", "t": "Vecinos, amistades, iglesia, clubes o barrio. Pueden ofrecer apoyo o reforzar el silencio y la vergüenza."}, {"h": "Servicios de salud", "t": "Ven a la niña en momentos clave. Pueden detectar necesidades médicas y psicológicas, y coordinar con otros servicios."}, {"h": "Protección y justicia", "t": "Evalúan el riesgo, dictan medidas y llevan procesos. Sus tiempos y sus formas pueden proteger o volver a exponer a la niña."}]}, {"bloque": "S4.2", "tipo": "texto", "titulo": "Cómo influye cada capa en la recuperación", "items": [{"h": "Hogar", "t": "Un hogar con adultos que creen, protegen y ponen límites favorece la recuperación. Un hogar donde la persona señalada sigue presente, o donde se minimiza lo ocurrido, la dificulta."}, {"h": "Escuela", "t": "Una escuela que observa sin interrogar, mantiene la rutina y coordina con salud puede ser un factor muy protector. Una que comenta el caso con otros estudiantes genera daño."}, {"h": "Comunidad", "t": "El estigma aumenta el silencio y el aislamiento. El apoyo comunitario, cuando existe, puede dar a la niña y a su familia otros lugares donde sentirse acogidas."}, {"h": "Servicios y justicia", "t": "Los procesos que escuchan una sola vez y coordinan su información reducen la revictimización. Los que repiten entrevistas y exponen detalles la aumentan."}], "destacado": "El contexto no es el fondo del caso. Es parte del plan de protección."}, {"bloque": "S4.2", "tipo": "texto", "titulo": "Lo que el contexto cambia en la intervención", "items": [{"h": "El lugar donde vive define lo posible", "t": "Un plan que depende de que la niña asista a sesiones semanales no funciona si no hay transporte, ni horarios compatibles con la escuela o el trabajo de sus cuidadores."}, {"h": "Quién puede acompañar", "t": "Si hay cuidadores protectores disponibles, la intervención puede apoyarse en ellos. Si no, se buscan otros adultos de confianza y se refuerza la red institucional."}, {"h": "La coordinación es parte del tratamiento", "t": "Un plan terapéutico que ignora lo que hace la escuela o el sistema de protección tiene huecos. Los distintos actores necesitan saber qué hace cada uno."}], "destacado": "Tratar a una niña como si viviera en un vacío es una forma de no verla."}, {"bloque": "S4.3", "tipo": "texto", "titulo": "Valorar la seguridad de hoy, sin investigar el pasado", "items": [{"h": "Amenazas actuales", "t": "¿Hay alguien que hoy amenace a la niña, a su familia o a sus cuidadores? ¿Ha habido situaciones nuevas desde la última evaluación?"}, {"h": "Contacto con la persona señalada", "t": "¿Hay contacto en la vida cotidiana? ¿Quién está presente en esos momentos, y quién puede verlo?"}, {"h": "Adultos que pueden proteger", "t": "¿Quién cree a la niña, quién la acompaña y quién pone límites? Estas preguntas se hacen sobre el presente."}, {"h": "Necesidades urgentes", "t": "Alimentación, salud, sueño y lugar donde dormir. Una necesidad básica sin atender pone en riesgo a la niña tanto como cualquier otra cosa."}], "destacado": "Valorar la seguridad no es investigar hechos. Es preguntar qué protege hoy y qué amenaza sigue presente."}, {"bloque": "S4.3", "tipo": "texto", "titulo": "Cuándo una situación es urgente", "items": [{"h": "Riesgo inmediato de daño", "t": "Si hay una amenaza concreta o una razón para pensar que la niña está en peligro en este momento, la respuesta es inmediata y sigue el protocolo de urgencia."}, {"h": "Lesiones o malestar médico", "t": "Cualquier lesión, sangrado, infección o malestar físico que requiera atención se canaliza a salud sin demora. La valoración médica no espera a la evaluación psicológica."}, {"h": "Contacto no supervisado o intentos de contacto", "t": "Si la persona señalada intenta acercarse, o si la niña queda sin supervisión con ella, se actúa de inmediato con los servicios competentes."}], "destacado": "En una urgencia, esta clase no sustituye el protocolo. Lo que sí hace es recordar que el protocolo existe y debe conocerse antes."}, {"bloque": "S4.4", "tipo": "texto", "titulo": "Principios de un plan de seguridad y apoyo", "items": [{"h": "Finalidad clara", "t": "El plan dice para qué sirve: proteger a la niña, reducir un riesgo concreto o sostener una necesidad. Un plan que intenta todo termina sin dirección."}, {"h": "Participación según la edad", "t": "La niña o el niño participa en lo que puede entender y decidir, con lenguaje apropiado. Su opinión importa aunque no decida sola."}, {"h": "Responsabilidades definidas", "t": "Para cada acción hay un responsable, una fecha y una forma de saber si se cumplió."}, {"h": "Revisión programada", "t": "El plan se revisa en fechas definidas o cuando cambia la situación. Un plan que no se revisa se vuelve obsoleto."}], "destacado": "Un buen plan es breve, claro y compartido por quienes lo ejecutan."}, {"bloque": "S4.4", "tipo": "tarjetas", "titulo": "Actores y su función: nadie hace todo", "intro": "Cada actor cumple una función específica. La coordinación consiste en que sus funciones se complementen sin duplicarse ni dejar vacíos.", "items": [{"h": "Cuidadores protectores", "t": "Apoyo y vigilancia cotidiana, dentro de lo que es seguro, con información y acompañamiento."}, {"h": "Escuela", "t": "Rutina, adultos de referencia y avisos según el protocolo. Mantiene la privacidad del caso."}, {"h": "Servicios de salud", "t": "Valoración médica, registro clínico y coordinación con la atención psicológica."}, {"h": "Servicios de protección", "t": "Evaluación del riesgo y medidas de protección, conforme a su competencia."}, {"h": "Especialistas", "t": "Atención psicológica, evaluaciones específicas y peritajes cuando corresponda."}], "destacado": "Si dos actores hacen lo mismo, algo queda sin hacer. Por eso la coordinación se define por escrito."}, {"bloque": "S4.5", "tipo": "texto", "titulo": "Interés superior de la niñez y derecho a ser escuchado", "items": [{"h": "Interés superior de la niñez", "t": "La Ley General de los Derechos de Niñas, Niños y Adolescentes lo establece como principio que guía las decisiones que les afectan. Se traduce en poner su bienestar y su seguridad por encima de otras consideraciones."}, {"h": "Derecho a ser escuchado", "t": "Niñas, niños y adolescentes tienen derecho a expresar su opinión según su edad y madurez. Escuchar no significa que decidan sin apoyo, sino que su voz cuente."}, {"h": "Derecho a protección y a no revictimizarse", "t": "La ley reconoce el derecho a la protección frente a la violencia, y exige que los procedimientos eviten exponerlos de nuevo a lo que vivieron."}], "destacado": "La ley se aplica en cada entidad y ámbito. Consulta el texto vigente antes de usarlo en un caso."}, {"bloque": "S4.5", "tipo": "texto", "titulo": "La NOM-046-SSA2-2005: alcance en los servicios de salud", "items": [{"h": "Qué establece", "t": "La NOM-046-SSA2-2005 fija criterios para la prevención y la atención de la violencia familiar y sexual en los servicios de salud. Describe procesos de atención, registro y referencia."}, {"h": "Qué no hace", "t": "No describe todas las responsabilidades de todos los roles profesionales, ni sustituye a las leyes penales y civiles de cada entidad. Su alcance es el del sector salud."}, {"h": "Cómo se aplica", "t": "Depende de la institución, del tipo de servicio y de la profesión. Conviene consultar la versión oficial vigente y el protocolo interno de la unidad."}], "destacado": "No extiendas automáticamente las obligaciones del sector salud a todos los roles clínicos."}, {"bloque": "S4.5", "tipo": "texto", "titulo": "Obligaciones, confidencialidad y notificación: qué verificar", "items": [{"h": "La entidad federativa", "t": "Las leyes y códigos penales estatales pueden tener diferencias en la definición de delitos, en los plazos y en las obligaciones de notificación."}, {"h": "La profesión", "t": "Cada profesión tiene su código de ética, con criterios de confidencialidad y de comunicación. Revísalo antes de decidir si compartir información."}, {"h": "La institución", "t": "Los protocolos internos definen pasos, responsables y formatos. Suelen ser la guía más concreta para actuar."}, {"h": "La vigencia y la asesoría", "t": "Las normas cambian. Verifica la versión vigente y consulta con asesoría jurídica o con protección infantil de tu jurisdicción."}], "destacado": "Antes de decidir si notificar, verifica la obligación que aplica a tu entidad, tu profesión y tu institución."}, {"bloque": "S4.6", "tipo": "texto", "titulo": "Límites del rol clínico ante una sospecha o una revelación", "items": [{"h": "No investigar ni confrontar", "t": "El clínico no reconstruye hechos ni confronta a la persona señalada. Esa tarea corresponde a otras instancias."}, {"h": "No prometer resultados", "t": "No se promete que el agresor será castigado, que la familia se separará ni que el proceso será rápido. Se explica lo que sí se puede hacer."}, {"h": "Reconocer la competencia", "t": "Si el caso excede la formación o la experiencia, se deriva o se consulta con supervisión. Un límite reconocido protege a la niña."}, {"h": "Cuidar al profesional", "t": "Escuchar relatos de violencia genera un desgaste real. Tener supervisión, pares y espacios de descarga es parte de un trabajo responsable."}], "destacado": "Reconocer lo que no te corresponde hacer es una forma de protección, no de abandono."}, {"bloque": "S4.6", "tipo": "texto", "titulo": "Documentación objetiva: qué registrar y qué no", "items": [{"h": "Lo que sí se registra", "t": "Fecha, contexto y acciones realizadas. Las palabras espontáneas de la niña, tal como se dijeron, entre comillas. Las observaciones directas, descritas sin interpretar."}, {"h": "Lo que se separa", "t": "Lo que se dice, lo que se observa y lo que se supone deben aparecer en secciones distintas. Una hipótesis escrita como dato se vuelve una conclusión."}, {"h": "Lo que no corresponde", "t": "Conclusiones periciales o jurídicas que están fuera de tu competencia. Tampoco se anotan juicios sobre la familia sin evidencia."}], "destacado": "Un buen registro protege a la niña, al profesional y a cualquier proceso posterior."}, {"bloque": "S4.6", "tipo": "texto", "titulo": "Compartir información: solo lo necesario, solo con quien debe", "items": [{"h": "El propósito define lo que se comparte", "t": "Se comparte la información mínima necesaria para proteger o para atender, nunca el expediente completo ni detalles que no le sirvan a quien lo recibe."}, {"h": "A quien tiene una función", "t": "La información va a quien tiene responsabilidad en el caso. No se comparte con la persona señalada, ni con personas que no tienen un rol."}, {"h": "Registrar lo que se comparte", "t": "Se anota a quién, cuándo, qué y con qué motivo. Este registro protege a la niña y permite revisar después si la comunicación fue adecuada."}], "destacado": "Proteger la privacidad de la niña también es protegerla de la estigmatización."}, {"bloque": "S4.7", "tipo": "caso", "titulo": "Caso integrador: Valeria, seis meses después", "intro": "Valeria tiene 10 años. Seis meses después de la primera consulta, la valoración médica está en curso. Su mamá asiste a algunas sesiones, a veces con dudas y a veces con enojo. La pareja de su mamá vive en casa, y la persona señalada sigue presente en la vida cotidiana de la niña. La abuela la cuida algunas tardes. La escuela pide que Valeria «ya lo supere», y hay un proceso judicial en curso en el que ella ya fue entrevistada en dos ocasiones.", "items": [{"h": "Pregunta 1", "t": "¿Cuál es la prioridad de protección hoy?"}, {"h": "Pregunta 2", "t": "¿Qué información debe coordinarse, y con quién?"}, {"h": "Pregunta 3", "t": "¿Qué objetivos terapéuticos son razonables, y qué criterios de seguimiento usarías?"}]}, {"bloque": "S4.8", "tipo": "flujo", "titulo": "Seguridad, escucha, evaluación, coordinación y seguimiento", "items": [{"h": "Seguridad", "t": "Lo primero es que la niña esté a salvo, hoy y en el entorno inmediato."}, {"h": "Escucha y vínculo", "t": "Un adulto que cree, acompaña y explica lo que sigue, sin presionar el relato."}, {"h": "Evaluación y plan", "t": "Formular el caso con datos, hipótesis y faltantes, y definir prioridades y objetivos."}, {"h": "Coordinación y seguimiento", "t": "Actores con funciones claras, información mínima y revisiones programadas."}], "destacado": "Una formulación clínica no determina culpabilidad ni sustituye la investigación ni la valoración especializada."}, {"bloque": "Referencias", "tipo": "texto", "titulo": "Fuentes de referencia y límites de uso", "items": [{"h": "OMS (2017)", "t": "Responding to Children and Adolescents Who Have Been Sexually Abused: WHO Clinical Guidelines. https://www.ncbi.nlm.nih.gov/books/NBK493119/"}, {"h": "OMS (2019)", "t": "WHO Guidelines for the Health Sector Response to Child Maltreatment. https://www.who.int/publications/m/item/who-guidelines-for-the-health-sector-response-to-child-maltreatment"}, {"h": "NICE NG116", "t": "Post-traumatic stress disorder: recommendations. https://www.nice.org.uk/guidance/ng116/chapter/Recommendations"}, {"h": "México", "t": "Ley General de los Derechos de Niñas, Niños y Adolescentes (texto consultado con reforma al 15 de enero de 2026): https://www.diputados.gob.mx/LeyesBiblio/pdf/LGDNNA.pdf · NOM-046-SSA2-2005, Secretaría de Salud: https://www.gob.mx/salud/cnegssr/documentos/norma-046-en-el-dof"}], "destacado": "Material educativo. Verifica la vigencia de normas, guías y protocolos de tu entidad antes de impartir o de aplicar cualquier criterio."}]}, {"n": 5, "kicker": "Sesión 5 · Módulo complementario · 3 horas · bloques S5.1 a S5.7", "titulo": "Intervención no farmacológica en el psicotrauma infantil", "subtitulo": "Qué intervenciones psicológicas y psicosociales tienen respaldo, para quién y en qué orden. Material educativo: no sustituye la formación certificada en cada modelo ni la supervisión clínica.", "pausa": "Pausa de 10 minutos entre S5.3 y S5.4. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "La intervención psicológica es la primera línea en el psicotrauma infantil. Esta sesión recorre qué se hace antes, durante y después de una intervención focalizada en trauma, y cómo cambia según la edad, el contexto y la complejidad del caso.", "items": [{"h": "Primero la seguridad", "t": "Por qué ninguna técnica funciona si la niña o el niño sigue expuesto, y qué se hace mientras se estabiliza la situación."}, {"h": "Intervenciones con respaldo", "t": "Qué son la TCC focalizada en trauma, el EMDR y las psicoterapias diádicas, y qué dicen las guías sobre cada una."}, {"h": "Ajustar a la edad", "t": "Cómo cambia la intervención en preescolares, escolares y adolescentes, y qué papel tienen los cuidadores en cada etapa."}, {"h": "Trauma complejo y escuela", "t": "Qué se agrega cuando el trauma fue repetido y vincular, y cómo apoyan la escuela y la comunidad."}]}, {"bloque": "S5.1", "tipo": "texto", "titulo": "Por qué la intervención psicológica es la primera línea", "items": [{"h": "Es lo que tiene más evidencia", "t": "Las guías internacionales, como las de NICE y la OMS, ubican las intervenciones psicológicas focalizadas en trauma como el tratamiento de primera elección para el TEPT en niños y adolescentes."}, {"h": "Trabaja sobre el mecanismo", "t": "El trauma deja recuerdos que irrumpen, evitación y una sensación de peligro constante. Las intervenciones focalizadas ayudan a procesar el recuerdo y a recuperar la sensación de control, en lugar de solo atenuar síntomas."}, {"h": "Incluye a los adultos", "t": "En la infancia, la recuperación depende mucho de quién cuida. Casi todos los modelos con respaldo trabajan también con los cuidadores protectores."}, {"h": "No todo malestar requiere terapia focalizada", "t": "Después de un evento, muchas reacciones son esperables y disminuyen con apoyo y tiempo. La intervención focalizada se reserva para síntomas que persisten o interfieren."}], "destacado": "La pregunta no es qué técnica aplicar, sino qué necesita esta niña o este niño hoy, con estos cuidadores y en este contexto."}, {"bloque": "S5.1", "tipo": "flujo", "titulo": "Una secuencia que ordena la intervención", "items": [{"h": "Seguridad", "t": "Confirmar que la exposición terminó o que hay un plan de protección en marcha. Sin esto, se trabaja en estabilizar, no en procesar el recuerdo."}, {"h": "Estabilización", "t": "Psicoeducación, rutinas, sueño, estrategias de regulación y fortalecimiento del vínculo con un adulto protector."}, {"h": "Procesamiento", "t": "Trabajo focalizado con el recuerdo traumático, con un modelo con respaldo y a un ritmo que la niña o el niño pueda sostener."}, {"h": "Integración", "t": "Recuperar la vida cotidiana: escuela, amistades, juego, proyectos. Prevenir recaídas y preparar el cierre."}], "destacado": "Las fases no son rígidas: se avanza y se retrocede según la seguridad y la regulación de cada momento."}, {"bloque": "S5.2", "tipo": "texto", "titulo": "Lo que se hace en las primeras semanas", "items": [{"h": "Primera ayuda psicológica", "t": "Ofrecer seguridad, calma, conexión con personas de apoyo e información práctica. Se escucha sin presionar a contar y se identifican necesidades urgentes."}, {"h": "Vigilancia activa", "t": "Durante el primer mes, muchas reacciones disminuyen solas. Se programa un seguimiento para revisar síntomas, en lugar de esperar a que la familia regrese por su cuenta."}, {"h": "Lo que no se recomienda", "t": "Las sesiones únicas de «descarga emocional», en las que se pide narrar el evento con detalle poco después de ocurrido, no previenen el TEPT y pueden aumentar el malestar."}], "destacado": "Acompañar sin forzar el relato es una intervención en sí misma, no una espera pasiva."}, {"bloque": "S5.2", "tipo": "tarjetas", "titulo": "Estabilización: la base de cualquier tratamiento", "intro": "Estas intervenciones se usan desde el inicio y acompañan todo el proceso. No sustituyen el trabajo focalizado, pero lo hacen posible.", "items": [{"h": "Psicoeducación", "t": "Explicar a la niña o el niño y a sus cuidadores qué es una reacción al trauma, por qué ocurre y que tiene tratamiento. Disminuye la culpa y la sensación de estar «roto»."}, {"h": "Regulación", "t": "Respiración, relajación muscular, anclaje en el presente y nombrar emociones. Se practican primero en calma, para poder usarlas cuando aparece el malestar."}, {"h": "Sueño y rutinas", "t": "Horarios predecibles, un ritual para dormir y una persona disponible por la noche. El sueño mejora la regulación y la tolerancia al tratamiento."}, {"h": "Cuidadores", "t": "Enseñar a responder a las reacciones sin castigo ni sobreprotección, y cuidar el propio malestar del adulto, que a menudo también está afectado."}]}, {"bloque": "S5.3", "tipo": "tarjetas", "titulo": "TCC focalizada en trauma: los componentes del modelo", "intro": "Es la intervención con más evidencia en niños y adolescentes de 3 a 18 años. Sus componentes se agrupan en la sigla PRACTICE y suelen trabajarse en unas 12 a 16 sesiones, más en trauma complejo.", "items": [{"h": "Psicoeducación y crianza", "t": "Información sobre el trauma y habilidades para los cuidadores, como el refuerzo positivo y el manejo de conductas."}, {"h": "Relajación y afecto", "t": "Técnicas para calmar el cuerpo y para identificar, nombrar y modular las emociones."}, {"h": "Afrontamiento cognitivo", "t": "Reconocer la relación entre pensamiento, emoción y conducta, y revisar ideas como «fue mi culpa»."}, {"h": "Narrativa del trauma", "t": "Construir, de forma gradual, un relato de lo vivido para procesarlo y corregir creencias distorsionadas."}, {"h": "Exposición en vivo y sesiones conjuntas", "t": "Enfrentar de forma gradual lo que se evita sin peligro real, y compartir la narrativa con el cuidador protector."}, {"h": "Seguridad", "t": "Habilidades de protección, cuidado del cuerpo y plan para el futuro, adaptados a la edad."}]}, {"bloque": "S5.3", "tipo": "texto", "titulo": "La narrativa del trauma no es contar lo que pasó", "items": [{"h": "Tiene un propósito terapéutico", "t": "No se busca reconstruir los hechos ni obtener detalles. Se busca que el recuerdo deje de irrumpir y que la niña o el niño pueda pensarlo sin desbordarse."}, {"h": "Se prepara antes", "t": "Solo se inicia cuando hay seguridad, habilidades de regulación y un adulto protector que acompaña. Antes de eso, abrir el recuerdo puede dañar."}, {"h": "Es gradual y tiene formas distintas", "t": "Puede ser un libro, un dibujo, una línea de vida o un relato escrito. Se avanza a su ritmo y se cierra cada sesión con regulación."}, {"h": "No se mezcla con lo judicial", "t": "La narrativa terapéutica no es una declaración. Si hay un proceso legal, se coordina con quien corresponde para no exponer a la persona dos veces."}], "destacado": "Procesar un recuerdo es distinto de repetirlo. La diferencia está en la preparación, el ritmo y el acompañamiento."}, {"bloque": "S5.4", "tipo": "texto", "titulo": "EMDR y otras intervenciones focalizadas", "items": [{"h": "EMDR", "t": "Desensibilización y reprocesamiento por movimientos oculares. La OMS lo recomienda, junto con la TCC focalizada en trauma, para niños y adolescentes con TEPT. NICE lo considera en escolares y adolescentes cuando la TCC focalizada no funcionó o no fue aceptada."}, {"h": "Terapia de exposición narrativa para niños (KIDNET)", "t": "Se ha estudiado sobre todo en niñas y niños expuestos a violencia organizada, guerra o migración forzada, con resultados alentadores."}, {"h": "Lo que tienen en común", "t": "Todas trabajan el recuerdo traumático de forma estructurada, incluyen estabilización previa y requieren formación específica y supervisión."}], "destacado": "Elegir entre modelos depende de la evidencia, de la formación disponible y de la preferencia informada de la familia."}, {"bloque": "S5.4", "tipo": "contraste", "titulo": "Primera infancia: la intervención pasa por el vínculo", "items": [{"h": "Menores de 6 años", "t": "El niño pequeño regula su malestar a través del adulto. Las psicoterapias diádicas, como la Psicoterapia Padre-Hijo, trabajan con el niño y su cuidador juntos y tienen ensayos que las respaldan.", "ej": "El juego y la relación con el cuidador son el lugar donde se procesa la experiencia."}, {"h": "Escolares y adolescentes", "t": "Pueden trabajar en sesiones individuales con más lenguaje y pensamiento. El cuidador sigue siendo central, pero con sesiones propias y algunas conjuntas.", "ej": "El adolescente participa en las decisiones del tratamiento y su opinión pesa."}], "destacado": "A menor edad, más peso tiene el adulto que cuida en el tratamiento."}, {"bloque": "S5.4", "tipo": "caso", "titulo": "Caso ficticio: Diego, 4 años", "intro": "Diego tiene 4 años. Hace dos meses presenció violencia grave entre adultos en su casa. Hoy vive con su mamá y su abuela, lejos de la persona agresora. Tiene pesadillas, se esconde cuando oye gritos, ha vuelto a mojar la cama y no se separa de su mamá. Ella está muy afectada y llora con frecuencia.", "items": [{"h": "Pregunta 1", "t": "¿Qué tipo de intervención te parece más adecuada para la edad de Diego?"}, {"h": "Pregunta 2", "t": "¿Qué necesita la mamá para poder ayudar a Diego?"}]}, {"bloque": "S5.5", "tipo": "texto", "titulo": "Trauma complejo: qué se agrega al tratamiento", "items": [{"h": "Más tiempo de estabilización", "t": "Cuando el trauma fue repetido y ocurrió dentro de los vínculos de cuidado, la regulación emocional y la confianza en los adultos necesitan más trabajo antes de abordar los recuerdos."}, {"h": "Modelos por fases", "t": "Modelos como ARC (apego, regulación y competencia) organizan la intervención alrededor de esos tres ejes, e incluyen el trabajo con cuidadores y con el sistema que rodea al niño. Su evidencia es más limitada que la de la TCC focalizada, pero va en aumento."}, {"h": "El sistema también se trata", "t": "En niñas y niños bajo cuidado institucional o con cambios frecuentes de hogar, la estabilidad del entorno es un objetivo terapéutico en sí mismo."}, {"h": "Expectativas realistas", "t": "La mejoría suele ser más lenta y con altibajos. Medir avances pequeños ayuda a sostener el tratamiento."}], "destacado": "En trauma complejo, la relación terapéutica estable ya es una parte de la intervención."}, {"bloque": "S5.6", "tipo": "tarjetas", "titulo": "Escuela, grupo y comunidad", "intro": "No toda la intervención ocurre en consultorio. Estos espacios pueden sostener la recuperación o volver a exponer al niño.", "items": [{"h": "Intervención grupal en la escuela", "t": "Programas estructurados de TCC en grupo, como CBITS, han mostrado reducir síntomas en estudiantes expuestos a violencia."}, {"h": "Escuela sensible al trauma", "t": "Docentes que entienden las reacciones, ofrecen un lugar seguro para regularse y evitan castigos que repiten la experiencia de amenaza."}, {"h": "Actividad física y juego", "t": "Recuperan la sensación de cuerpo seguro y de disfrute. Acompañan al tratamiento, pero no lo sustituyen."}, {"h": "Comunidad y cultura", "t": "Las redes de apoyo, las creencias y el idioma de la familia influyen en cómo se entiende el trauma y en qué ayuda se acepta."}]}, {"bloque": "S5.6", "tipo": "contraste", "titulo": "Apoyo complementario o tratamiento principal", "items": [{"h": "Tratamiento principal", "t": "Intervención focalizada en trauma con respaldo en estudios controlados, aplicada por un profesional formado y supervisado, con seguimiento de síntomas.", "ej": "TCC focalizada en trauma, EMDR, psicoterapia diádica en la primera infancia."}, {"h": "Apoyo complementario", "t": "Actividades que mejoran el bienestar, la regulación o el vínculo, y que acompañan al tratamiento sin sustituirlo cuando hay TEPT.", "ej": "Arte, deporte, música, mascotas, grupos recreativos."}], "destacado": "Lo complementario suma. El problema aparece cuando se ofrece en lugar de un tratamiento que sí funciona."}, {"bloque": "S5.7", "tipo": "texto", "titulo": "Cómo saber si la intervención está funcionando", "items": [{"h": "Medir antes, durante y al final", "t": "Escalas breves de síntomas postraumáticos, como la CATS o la CPSS-5, aplicadas al inicio y de forma periódica, permiten ver si hay cambio real."}, {"h": "Mirar la vida cotidiana", "t": "El sueño, la asistencia y el rendimiento escolar, el juego y las amistades son indicadores tan importantes como los síntomas."}, {"h": "Revisar si no hay mejoría", "t": "Se revisa la seguridad, la adherencia, la fidelidad al modelo, las comorbilidades y la situación del cuidador antes de cambiar de intervención."}], "destacado": "Si después de un tiempo razonable no hay cambio, se revisa el caso en supervisión, no se insiste con lo mismo."}, {"bloque": "S5.7", "tipo": "tarjetas", "titulo": "Síntesis: cinco ideas para llevarte de esta sesión", "items": [{"h": "La seguridad va primero", "t": "Sin protección, se estabiliza; no se procesa el recuerdo."}, {"h": "La intervención psicológica es la primera línea", "t": "La TCC focalizada en trauma tiene la mayor evidencia en la infancia."}, {"h": "La edad cambia el formato", "t": "A menor edad, más trabajo con el cuidador."}, {"h": "Trauma complejo pide más tiempo", "t": "Más estabilización y más trabajo con el sistema."}, {"h": "Lo que no se mide, no se sabe", "t": "Seguir los síntomas permite ajustar a tiempo."}], "destacado": "La sesión 6 revisa qué lugar tienen los medicamentos dentro de este plan."}]}, {"n": 6, "kicker": "Sesión 6 · Módulo complementario · 3 horas · bloques S6.1 a S6.7", "titulo": "Psicofarmacología en el psicotrauma infantil: uso prudente", "subtitulo": "Qué lugar tienen los medicamentos, qué evidencia existe y cómo acompañar un tratamiento aunque no se prescriba. No incluye dosis. Material educativo: no sustituye la valoración por paidopsiquiatría ni la información de prescripción vigente.", "pausa": "Pausa de 10 minutos entre S6.3 y S6.4. Puedes omitirla al ver la grabación.", "slides": [{"bloque": "Inicio", "tipo": "tarjetas", "titulo": "Qué vamos a entender en esta sesión", "intro": "Muchas niñas y niños con historia de trauma reciben medicamentos, a veces varios a la vez. Esta sesión ayuda a entender cuándo pueden ayudar, cuándo no y qué debe vigilar cualquier profesional del equipo, prescriba o no.", "items": [{"h": "El lugar del medicamento", "t": "Por qué el tratamiento del TEPT infantil es psicológico y en qué casos un fármaco se suma al plan."}, {"h": "La evidencia disponible", "t": "Qué se sabe de antidepresivos, alfa-agonistas, prazosina, antipsicóticos y otros fármacos en esta población."}, {"h": "Riesgos y polifarmacia", "t": "Efectos adversos, advertencias y el problema de acumular medicamentos sin revisión."}, {"h": "Trabajo en equipo y ética", "t": "Qué necesita saber cada profesión, cómo comunicar efectos y cómo incluir a la niña o el niño en la decisión."}]}, {"bloque": "S6.1", "tipo": "texto", "titulo": "El medicamento no trata el trauma: puede tratar síntomas y comorbilidades", "items": [{"h": "Lo que dicen las guías", "t": "NICE no recomienda medicamentos para prevenir el TEPT en niños y adolescentes, y no incluye ningún fármaco como tratamiento del TEPT en esta población. La Academia Americana de Psiquiatría Infantil y del Adolescente también ubica la psicoterapia como primera línea."}, {"h": "Por qué", "t": "Los ensayos con antidepresivos en niños y adolescentes con TEPT no mostraron una ventaja clara sobre el placebo, y agregar un antidepresivo a la TCC focalizada en trauma aportó poco beneficio adicional."}, {"h": "Dónde sí puede ayudar", "t": "Cuando hay depresión moderada o grave, ansiedad intensa, TDAH, insomnio grave o agitación que pone en riesgo a la persona, y esos síntomas impiden participar en el tratamiento psicológico."}], "destacado": "Un medicamento puede abrir espacio para la terapia. No la sustituye."}, {"bloque": "S6.1", "tipo": "flujo", "titulo": "Antes de pensar en un medicamento", "items": [{"h": "Seguridad", "t": "¿Sigue expuesto? Ningún fármaco compensa un entorno inseguro, y la agitación puede ser una respuesta a una amenaza real."}, {"h": "Evaluación completa", "t": "Confirmar el diagnóstico, buscar comorbilidades y descartar causas médicas del síntoma, como dolor, problemas de tiroides o efectos de otros fármacos."}, {"h": "Intervención psicológica", "t": "¿Recibe un tratamiento con respaldo, con suficiente tiempo y fidelidad? ¿Se revisó por qué no hay mejoría?"}, {"h": "Valoración especializada", "t": "Si persisten síntomas graves que interfieren, la valoración por paidopsiquiatría decide si un medicamento se suma al plan."}], "destacado": "La pregunta correcta no es qué medicamento dar, sino qué síntoma, con qué objetivo y por cuánto tiempo."}, {"bloque": "S6.2", "tipo": "tarjetas", "titulo": "Síntomas que suelen motivar la consulta farmacológica", "intro": "En la práctica, el medicamento se considera por síntomas concretos que se pueden medir, no por la etiqueta de trauma.", "items": [{"h": "Sueño y pesadillas", "t": "Insomnio que persiste pese a rutinas y manejo conductual, o pesadillas que impiden descansar y afectan el día."}, {"h": "Hiperactivación", "t": "Sobresalto, irritabilidad e hipervigilancia intensas que dificultan la escuela y la convivencia."}, {"h": "Ánimo y ansiedad", "t": "Depresión moderada o grave, ideación suicida o ansiedad que impide participar en la terapia."}, {"h": "Agresión y desregulación grave", "t": "Conductas que ponen en riesgo a la persona o a otros, cuando las medidas de seguridad y conductuales no alcanzan."}, {"h": "Atención e impulsividad", "t": "Síntomas de TDAH, que pueden coexistir con el trauma o confundirse con hiperactivación."}]}, {"bloque": "S6.3", "tipo": "texto", "titulo": "Antidepresivos ISRS: útiles para comorbilidades, no como tratamiento del TEPT", "items": [{"h": "Qué se sabe", "t": "Los estudios controlados con sertralina en niños y adolescentes con TEPT no mostraron diferencias claras frente al placebo. Su papel principal es tratar la depresión o la ansiedad que acompañan al trauma."}, {"h": "Advertencia de seguridad", "t": "Los antidepresivos llevan una advertencia por aumento del riesgo de pensamientos y conductas suicidas en niños, adolescentes y adultos jóvenes. Esto exige vigilancia estrecha, sobre todo en las primeras semanas y al cambiar la dosis."}, {"h": "Qué vigilar", "t": "Inquietud, cambios bruscos de ánimo, desinhibición, alteraciones del sueño y molestias digestivas. Cualquier profesional del equipo puede detectarlos y debe comunicarlos."}], "destacado": "Si una niña o un niño empieza un antidepresivo, todo el equipo sabe qué observar y a quién avisar."}, {"bloque": "S6.3", "tipo": "texto", "titulo": "Pesadillas e hiperactivación: alfa-agonistas y prazosina", "items": [{"h": "Alfa-agonistas", "t": "La clonidina y la guanfacina se usan en niños con TDAH y, fuera de indicación, para hiperactivación e impulsividad asociadas al trauma. La evidencia en TEPT infantil proviene de estudios abiertos pequeños."}, {"h": "Prazosina", "t": "Se ha usado para pesadillas relacionadas con trauma. En adultos los resultados son contradictorios, y en niños la evidencia se limita a series de casos y estudios pequeños."}, {"h": "Qué vigilar", "t": "Somnolencia, mareo y baja de la presión arterial, sobre todo al iniciar. Los alfa-agonistas no deben suspenderse de golpe."}], "destacado": "Menos evidencia no significa que esté prohibido, sino que exige un objetivo claro, medición y revisión."}, {"bloque": "S6.4", "tipo": "texto", "titulo": "Antipsicóticos, benzodiacepinas y otros fármacos", "items": [{"h": "Antipsicóticos", "t": "Se reservan para agresión grave, desregulación que pone en riesgo o síntomas psicóticos, con valoración especializada. Tienen efectos metabólicos importantes, como aumento de peso y alteraciones de glucosa y lípidos, que requieren monitoreo."}, {"h": "Benzodiacepinas", "t": "No se recomiendan de forma rutinaria en el trauma infantil. Pueden causar desinhibición paradójica en niños, generan dependencia y no tratan el TEPT."}, {"h": "Melatonina y sueño", "t": "Puede considerarse con indicación médica para dificultad para iniciar el sueño, después de trabajar rutinas y manejo conductual. La evidencia específica en trauma es escasa."}], "destacado": "Cuanto mayor es el riesgo del fármaco, más claro debe estar el objetivo y más cercano el seguimiento."}, {"bloque": "S6.4", "tipo": "contraste", "titulo": "Leer un tratamiento farmacológico, aunque no se prescriba", "items": [{"h": "Preguntas que cualquiera puede hacer", "t": "¿Para qué síntoma se indicó? ¿Desde cuándo lo toma? ¿Quién lo revisa y cada cuánto? ¿Qué efectos se esperan y cuáles son señales de alarma?", "ej": "Enfermería, psicología y trabajo social observan al niño más seguido que quien prescribe."}, {"h": "Lo que corresponde a quien prescribe", "t": "Indicar, ajustar o retirar el medicamento, elegir la dosis y decidir el seguimiento médico necesario.", "ej": "Quien no prescribe no suspende ni cambia la indicación: comunica lo que observa."}], "destacado": "Un buen equipo no deja la vigilancia del medicamento solo en manos de quien lo indicó."}, {"bloque": "S6.5", "tipo": "texto", "titulo": "Polifarmacia: cuando los medicamentos se acumulan", "items": [{"h": "Un problema documentado", "t": "En niñas y niños bajo cuidado institucional o en acogimiento se ha documentado el uso de varios psicofármacos a la vez, con frecuencia mayor que en otros niños."}, {"h": "Cómo ocurre", "t": "Cambios de médico, de institución o de hogar; cada profesional agrega un fármaco para un síntoma nuevo, y nadie revisa el conjunto."}, {"h": "Por qué importa", "t": "Más medicamentos significan más efectos adversos e interacciones, y a veces síntomas causados por los propios fármacos que se tratan con otro fármaco."}, {"h": "Revisar y retirar", "t": "Una revisión periódica pregunta si cada medicamento sigue siendo necesario. Retirarlos de forma gradual y supervisada también es parte del tratamiento."}], "destacado": "Cada medicamento debe tener un motivo vigente, un responsable y una fecha de revisión."}, {"bloque": "S6.5", "tipo": "caso", "titulo": "Caso ficticio: Sofía, 13 años", "intro": "Sofía tiene 13 años y vive en una casa hogar desde hace un año, después de una historia de violencia sexual en su familia. Ha cambiado de institución dos veces. Toma un antidepresivo, un antipsicótico y un medicamento para dormir, indicados por médicos distintos. Duerme mucho de día, subió de peso y dice que «nada sirve». No ha recibido terapia focalizada en trauma.", "items": [{"h": "Pregunta 1", "t": "¿Qué te preocupa de su tratamiento actual?"}, {"h": "Pregunta 2", "t": "¿Qué pasos propondrías al equipo, según tu rol?"}]}, {"bloque": "S6.6", "tipo": "tarjetas", "titulo": "Ética: consentimiento, asentimiento y participación", "intro": "Decidir un medicamento en la infancia implica a la niña o el niño, a sus cuidadores y, en algunos casos, a las instituciones de protección.", "items": [{"h": "Consentimiento de quien tiene la tutela", "t": "Información clara sobre el objetivo, la evidencia, los efectos adversos, las alternativas y la duración prevista. En niños bajo protección, se verifica quién puede consentir."}, {"h": "Asentimiento del niño", "t": "Explicar con palabras adecuadas a su edad para qué es el medicamento, qué puede sentir y que puede decir si algo no le gusta. Su opinión cuenta."}, {"h": "No usar el fármaco para controlar", "t": "Un medicamento no se indica para que un niño «se porte bien» en una institución o para compensar la falta de personal o de cuidado."}]}, {"bloque": "S6.7", "tipo": "flujo", "titulo": "Seguir un tratamiento farmacológico paso a paso", "items": [{"h": "Objetivo", "t": "Definir el síntoma a tratar y cómo se medirá, antes de iniciar."}, {"h": "Línea de base", "t": "Registrar síntomas, sueño, peso y otros datos que el fármaco puede afectar."}, {"h": "Seguimiento", "t": "Revisar en fechas definidas, con la observación de todo el equipo y de la familia."}, {"h": "Revisión", "t": "Decidir si continuar, ajustar o retirar. Ningún medicamento se queda sin fecha de revisión."}], "destacado": "Lo que no tiene objetivo medible no se puede evaluar, y lo que no se evalúa tiende a quedarse."}, {"bloque": "S6.7", "tipo": "tarjetas", "titulo": "Síntesis: cinco ideas para llevarte de esta sesión", "items": [{"h": "La terapia es la primera línea", "t": "Ningún fármaco trata el TEPT infantil por sí solo."}, {"h": "Se trata un síntoma, no el trauma", "t": "El medicamento se dirige a comorbilidades o síntomas graves medibles."}, {"h": "La evidencia es limitada", "t": "Más razón para tener objetivo, medición y revisión."}, {"h": "Todo el equipo vigila", "t": "Quien no prescribe observa, pregunta y comunica."}, {"h": "Revisar también es tratar", "t": "Retirar lo que no ayuda evita daños por polifarmacia."}], "destacado": "Dosis e indicaciones se verifican siempre con la información de prescripción vigente y con paidopsiquiatría."}, {"bloque": "Referencias", "tipo": "texto", "titulo": "Fuentes de referencia de los módulos complementarios", "items": [{"h": "NICE NG116 (2018)", "t": "Post-traumatic stress disorder: recommendations. https://www.nice.org.uk/guidance/ng116"}, {"h": "OMS (2013)", "t": "Guidelines for the management of conditions specifically related to stress. https://www.who.int/publications/i/item/9789241505406"}, {"h": "AACAP (2010)", "t": "Practice parameter for the assessment and treatment of children and adolescents with posttraumatic stress disorder. J Am Acad Child Adolesc Psychiatry, 49(4), 414–430."}, {"h": "Cohen, Mannarino y Deblinger", "t": "Treating Trauma and Traumatic Grief in Children and Adolescents (2.ª ed., 2017). Guilford Press."}], "destacado": "Material educativo. Verifica guías, indicaciones y advertencias vigentes antes de aplicar cualquier criterio."}]}], "glosario": [{"t": "Confidencialidad con límites", "d": "No se promete secreto absoluto. Se explica qué información se puede compartir, para qué y con quién, sobre todo cuando hace falta proteger a la persona."}, {"t": "Cuidador protector", "d": "Adulto que ofrece seguridad, credibilidad y apoyo de manera sostenida. Se evalúa caso por caso; no se asume por el parentesco."}, {"t": "Dato, observación e hipótesis", "d": "Dato: lo que alguien reporta. Observación: lo que se ve directamente y se registra sin interpretar. Hipótesis: una explicación posible que requiere confirmación."}, {"t": "Diagnóstico diferencial", "d": "Proceso para distinguir entre cuadros con síntomas parecidos y considerar si coexisten. Requiere evaluación de criterios, historia, curso y otras causas posibles."}, {"t": "Entrevista forense", "d": "Procedimiento investigativo o judicial, con protocolos y competencias propias. Es distinta del acompañamiento clínico y no debe mezclarse con él."}, {"t": "Interés superior de la niñez", "d": "Principio de la Ley General de los Derechos de Niñas, Niños y Adolescentes: poner el bienestar y la seguridad de la niña o niño por encima de otras consideraciones en las decisiones que le afectan."}, {"t": "Intervención focalizada en trauma", "d": "Intervención diseñada para síntomas relacionados con el trauma. Se adapta al desarrollo y la aplican profesionales formados y supervisados."}, {"t": "Respuesta adaptativa al peligro", "d": "Alerta o evitación proporcionales a una amenaza real y actual. Se distingue de los síntomas que persisten cuando la amenaza ya cesó."}, {"t": "Revelación", "d": "Comunicación de una experiencia de abuso o violencia. Puede ser espontánea, parcial o gradual, y puede cambiar con el tiempo."}, {"t": "Revictimización", "d": "Daño adicional causado por respuestas que culpan, interrogan, desacreditan, exponen o obligan a repetir el relato."}, {"t": "TEPT", "d": "Trastorno de estrés postraumático. Es un diagnóstico con criterios específicos, que requiere evaluación clínica y que se adapta a la edad."}, {"t": "TEPT complejo", "d": "Diagnóstico de la CIE-11 que incluye los síntomas de TEPT y alteraciones adicionales en la autorregulación, la imagen de sí mismo y las relaciones. No existe en el DSM-5."}, {"t": "Trauma complejo", "d": "Término descriptivo para una historia de exposición repetida o prolongada a experiencias traumáticas, sobre todo interpersonales y de las que es difícil escapar. Por sí mismo no es un diagnóstico."}, {"t": "Trauma vicario", "d": "Efecto emocional que puede sufrir quien escucha de forma repetida relatos de violencia. Se previene con supervisión, pausas y apoyo entre pares."}, {"t": "Asentimiento", "d": "Acuerdo de la niña o el niño con una intervención, después de recibir una explicación adecuada a su edad. Complementa el consentimiento de quien tiene la tutela."}, {"t": "Desprescripción", "d": "Revisión planificada para reducir o retirar medicamentos que ya no son necesarios o que causan más daño que beneficio, de forma gradual y supervisada."}, {"t": "EMDR", "d": "Desensibilización y reprocesamiento por movimientos oculares. Intervención focalizada en trauma que la OMS recomienda para niños y adolescentes con TEPT."}, {"t": "Estabilización", "d": "Fase del tratamiento centrada en la seguridad, la regulación emocional, el sueño, las rutinas y el vínculo con un adulto protector, antes de trabajar el recuerdo traumático."}, {"t": "Polifarmacia", "d": "Uso simultáneo de varios medicamentos. En la infancia aumenta el riesgo de efectos adversos e interacciones y exige revisión periódica."}, {"t": "Psicoeducación", "d": "Explicación a la persona y a sus cuidadores sobre qué son las reacciones al trauma, por qué ocurren y cómo se tratan."}, {"t": "Psicoterapia diádica", "d": "Intervención que trabaja con el niño pequeño y su cuidador juntos, como la Psicoterapia Padre-Hijo. Es la base del tratamiento en la primera infancia."}, {"t": "TCC focalizada en trauma", "d": "Terapia cognitivo-conductual focalizada en trauma (TF-CBT). Modelo por componentes, resumidos en la sigla PRACTICE, con la mayor evidencia en niños y adolescentes."}, {"t": "Uso fuera de indicación", "d": "Empleo de un medicamento para un uso, edad o dosis distintos de los aprobados. Requiere justificación clínica, consentimiento informado y seguimiento."}]};
